export function FocusDemo({
  label = "{{label}}",
  value = "{{value}}",
  focused = {{focused}},
  accent = "{{accent}}",
  thickness = {{thickness}},
}) {
  return (
    <div style={{ width: 280, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 6 }}>{label}</label>
      <div style={{ padding: "10px 12px", borderRadius: 8, border: "1.5px solid " + (focused ? accent : "#24143033"), background: "#FAF7F2",
        outline: focused ? thickness + "px solid " + accent : "none", outlineOffset: 2 }}>
        {value}{focused && <span style={{ display: "inline-block", width: 1, height: 14, background: accent, marginLeft: 2 }} />}
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430aa" }}>{focused ? "shown with keyboard focus" : "rest state"}</p>
    </div>
  );
}
